def icon(name): return f'<svg class="icon" viewBox="0 0 24 24" aria-hidden="true">{ICONS[name]}</svg>'
def brand(): return f'<div class="brand"><span class="mark">{icon("leaf")}</span>AgriFlow<span style="color:var(--green)">.</span></div>'
def art(kind='potato'):
    shapes = {
    'potato':'<ellipse cx="88" cy="96" rx="49" ry="35" transform="rotate(-22 88 96)" fill="#B58A50"/><ellipse cx="142" cy="111" rx="49" ry="34" transform="rotate(19 142 111)" fill="#C89E62"/><ellipse cx="108" cy="70" rx="46" ry="31" transform="rotate(-9 108 70)" fill="#DAB47C"/><g fill="#A97B43"><ellipse cx="84" cy="64" rx="3" ry="2"/><ellipse cx="123" cy="74" rx="3" ry="2"/><ellipse cx="144" cy="110" rx="3" ry="2"/><ellipse cx="167" cy="123" rx="3" ry="2"/><ellipse cx="68" cy="105" rx="3" ry="2"/></g>',
    'tomato':'<circle cx="86" cy="103" r="39" fill="#C95035"/><circle cx="139" cy="104" r="42" fill="#E16B46"/><path d="m139 68-21 9 16 3 5 15 5-15 18-5-19-5 1-19-8 16Z" fill="#4C713E"/><path d="m85 68-17 9 14 2 5 12 4-13 14-5-15-3-1-14Z" fill="#4C713E"/>',
    'carrot':'<path d="m87 58 61 32-84 62Z" fill="#DE833E"/><path d="m104 65 24 9-19-45M118 77l35-27" fill="none" stroke="#5A7B40" stroke-width="10" stroke-linecap="round"/><path d="m91 89 17 9m-26 13 13 6" stroke="#B65C2B" stroke-width="4"/>',
    'cabbage':'<circle cx="111" cy="96" r="52" fill="#7C9D60"/><ellipse cx="101" cy="88" rx="36" ry="44" fill="#9CB979"/><path d="M111 143c-2-37-25-50-24-78m25 72c29-27 39-43 28-67m-29 47c-15-18-36-19-47-27" fill="none" stroke="#C5D5A9" stroke-width="4"/>',
    }
    return f'<svg viewBox="0 0 220 175" role="img" aria-label="{kind} illustration"><ellipse cx="112" cy="143" rx="68" ry="10" fill="#193F2C" opacity=".07"/>{shapes[kind]}</svg>'
def badge(text, tone=''): return f'<span class="badge {tone}">{escape(text)}</span>'
def button(text, target=None, secondary=False):
    cls='btn secondary' if secondary else 'btn'
    return f'<a class="{cls}" href="{target}.html">{text}</a>' if target else f'<button class="{cls}" disabled>{text}</button>'
def data(label,value): return f'<div class="data"><span class="muted">{label}</span><strong>{value}</strong></div>'
def card(body): return f'<div class="card">{body}</div>'
def heading(title,sub=''): return f'<div><h1>{title}</h1><p class="muted" style="margin-top:8px">{sub}</p></div>'
def field(label,value,hint=''): return f'<label class="field">{label}<input value="{value}" readonly aria-label="{label}"><small>{hint}</small></label>'
def section(title,link='',target=''): return f'<div class="sectionhead"><h2>{title}</h2>'+ (f'<a class="textlink" href="{target}.html">{link}</a>' if link else '')+'</div>'
def produce_card(title,kind,meta,price,target):
    return f'<a class="card row" href="{target}.html"><div class="produce {kind}" style="width:87px;height:88px">{art(kind)}</div><div class="grow"><h3>{title}</h3><p class="small muted">{meta}</p><p style="margin-top:8px"><strong>{price}</strong><span class="small muted"> / kg</span></p></div></a>'
SCREENS=[]
def save(key,title,role,body,desktop=False,active='home'):
    if desktop:
        nav=[('home','Overview','admin-overview'),('truck','Market operations','admin-queue'),('check','Inspections','admin-inspection'),('money','Payments','admin-payments')]
        side=''.join(f'<a class="{"active" if active==i else ""}" href="{dest}.html">{icon(i)}{label}</a>' for i,label,dest in nav)
        shell=f'<div class="desktop"><aside class="sidebar">{brand()}<div><p class="eyebrow muted" style="margin-bottom:15px">Market workspace</p><nav>{side}</nav></div><div class="note"><strong>One market. Better flow.</strong><p class="small" style="margin-top:7px">Dambulla Dedicated Economic Centre</p></div><div class="sidefoot row"><span class="avatar">NP</span><div><strong class="small">Nimali Perera</strong><p class="small muted">Administrator</p></div></div></aside><div class="workspace"><header class="topbar row between"><span class="small muted">Dambulla market <span style="margin:0 10px">/</span> {title}</span><div class="row">{badge("Market open")}<span class="small muted">03 Nov 2026</span><span class="avatar">NP</span></div></header><main class="deskcontent">{body}</main></div></div>'
    else:
        nav= [('home','Home','farmer-home'),('box','My lots','farmer-lots'),('offer','Offers','farmer-offers'),('truck','Visits','farmer-visit'),('user','Sales','farmer-settlement')] if role=='Farmer' else [('search','Explore','buyer-explore'),('offer','Offers','buyer-offers'),('clock','Reserved','buyer-reservation'),('money','Purchases','buyer-receipt')]
        if role=='Administrator':nav=[('truck','Queue','admin-mobile'),('check','Inspection','admin-inspection'),('home','Overview','admin-overview')]
        bottom=''.join(f'<a class="{"active" if i==active else ""}" href="{dest}.html">{icon(i)}{label}</a>' for i,label,dest in nav)
        shell=f'<div class="phone"><div class="status"><span>9:41</span><span>••• &nbsp; 5G &nbsp; ▰</span></div><header class="mobilehead">{brand()}<span class="avatar">{"SK" if role=="Farmer" else "NP" if role=="Administrator" else "AF"}</span></header><main class="content">{body}</main><nav class="bottomnav">{bottom}</nav></div>'
    doc=f'<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>{title} · AgriFlow</title><style>{CSS}</style></head><body>{shell}</body></html>'
    (OUT/f'{key}.html').write_text(doc,encoding='utf-8')
    SCREENS.append(dict(key=key,title=title,role=role,width=1440 if desktop else 390,desktop=desktop))

