def table(headers,rows):return '<table class="table"><thead><tr>'+''.join(f'<th>{h}</th>' for h in headers)+'</tr></thead><tbody>'+''.join('<tr>'+''.join(f'<td>{c}</td>' for c in row)+'</tr>' for row in rows)+'</tbody></table>'
def deskhead(title,sub,action=''):return '<div class="row between">'+heading(title,sub)+action+'</div>'
def metrics(items):return '<div class="deskmetrics">'+''.join(card(f'<p class="small muted">{l}</p><p class="metric" style="margin-top:8px">{v}</p><p class="small muted" style="margin-top:5px">{s}</p>') for l,v,s in items)+'</div>'
queue_rows=[['01','VIS-0238<br><span class="small muted">WP LD-4120</span>','Tomatoes · 150 kg','09:18',badge('Called','blue'),'Bay A1'],['02','VIS-0239<br><span class="small muted">CP DA-7821</span>','Carrots · 200 kg','09:22',badge('Waiting','amber'),'—'],['03','VIS-0240<br><span class="small muted">NC LC-1189</span>','Cabbage · 80 kg','09:28',badge('Waiting','amber'),'—'],['04','VIS-0241<br><span class="small muted">WP LD-4582</span>','Potatoes · 100 kg','09:35',badge('Waiting','amber'),'—']]
