save('admin-mobile','Gate & queue mobile','Administrator',heading('At the gate.','Zone A · Live operations')+'<div class="row between">'+badge('Updated 09:41')+'<span class="small muted">4 waiting · 1 bay free</span></div>'+card('<h2>Find a visit</h2><div style="margin-top:15px">'+field('Visit ID / vehicle','VIS-0241')+'</div><p class="small muted" style="margin-top:10px">Manual lookup is available alongside QR check-in.</p>')+'<div class="hero"><p class="eyebrow">Next eligible vehicle</p><h1>CP DA-7821</h1><p class="muted">VIS-0239 · Carrots · 200 kg</p><hr class="divider" style="opacity:.3"><div class="row between"><span>Checked in 09:22</span><strong>Bay A3 free</strong></div></div>'+button('Review dispatch on desktop','admin-queue')+section('Waiting in Zone A')+''.join(card(f'<div class="row"><span class="avatar">{p}</span><div class="grow"><h3>{v}</h3><p class="small muted">{d}</p></div>{badge("Waiting","amber")}</div>') for p,v,d in [('02','CP DA-7821','Carrots · 09:22'),('03','NC LC-1189','Cabbage · 09:28'),('04','WP LD-4582','Potatoes · 09:35')]),active='truck')

# A review board links to standalone sources; every source remains self-contained.
gallery=''
for role in ['Farmer','Buyer','Administrator']:
    gallery+=f'<section id="{role.lower()}"><div class="section-title"><span class="eyebrow">{role} experience</span><h2>{"From harvest to settlement" if role=="Farmer" else "Discover. Offer. Reserve." if role=="Buyer" else "A calmer market workspace"}</h2></div><div class="gallery">'
    for s in [x for x in SCREENS if x['role']==role]:
        gallery+=f'<article class="preview {"wide" if s["desktop"] else ""}"><div class="previewlabel"><span>{s["title"]}</span><a href="screens/{s["key"]}.html" target="_blank">Open ↗</a></div><div class="viewport"><iframe title="{s["title"]}" src="screens/{s["key"]}.html" loading="lazy"></iframe></div></article>'
    gallery+='</div></section>'
palette=''.join(f'<div><span style="display:block;background:{c};height:65px;border-radius:12px;margin-bottom:8px"></span><strong>{n}</strong><p class="small muted">{c}</p></div>' for n,c in [('Forest','#175C43'),('Deep green','#103E30'),('Fresh lime','#D8EEA5'),('Warm ivory','#F6F7F2'),('Ink','#20352C'),('Amber','#805519')])
boardcss='''header.board{padding:52px 5vw;background:var(--deep);color:white}.board h1{font-size:52px;max-width:780px;margin:22px 0}.board p{color:#D5E5DA;max-width:650px}.board nav{display:flex;gap:14px;margin-top:30px;flex-wrap:wrap}.board nav a{padding:10px 18px;border:1px solid #638272;border-radius:30px;font-size:13px}.boardmain{padding:38px 5vw}.section-title{margin:45px 0 24px}.section-title .eyebrow{color:var(--green)}.section-title h2{font-size:30px;margin-top:6px}.gallery{display:flex;gap:28px;flex-wrap:wrap;align-items:flex-start}.preview{width:390px}.previewlabel{display:flex;justify-content:space-between;font-size:13px;margin:0 0 12px;font-weight:600}.previewlabel a{color:var(--green)}.viewport{height:844px;overflow:hidden;border-radius:24px;border:1px solid var(--line);box-shadow:0 14px 40px #103e3010;background:white}.viewport iframe{width:390px;height:844px;border:0}.preview.wide{width:100%;max-width:1152px}.wide .viewport{height:800px;border-radius:16px;overflow:auto}.wide iframe{width:1440px;height:1000px;transform:scale(.8);transform-origin:top left}.palette{display:grid;grid-template-columns:repeat(6,1fr);gap:16px}.guide{display:grid;grid-template-columns:1fr 1fr;gap:22px;margin-top:22px}@media(max-width:500px){.board h1{font-size:36px}.boardmain{padding:24px 12px}.preview{width:100%}.viewport iframe{width:100%}.palette{grid-template-columns:repeat(3,1fr)}.guide{grid-template-columns:1fr}}'''
(ROOT/'index.html').write_text(f'<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Dambulla AgriFlow · UI design review</title><style>{CSS}{boardcss}</style></head><body><header class="board"><div class="eyebrow">Dambulla AgriFlow / Design direction 01</div><h1>Fresh thinking.<br>A better market day.</h1><p>A human-centred workspace for the people who grow, buy and move fresh produce. Mobile journeys for farmers and buyers. Clear operational tools for administrators.</p><nav><a href="#foundations">Foundations</a><a href="#farmer">Farmer mobile</a><a href="#buyer">Buyer mobile</a><a href="#administrator">Administrator</a></nav></header><main class="boardmain"><div class="note amber">Local design review · {len(SCREENS)} screens · illustrative data. These designs have not yet been created in Figma. Links simulate journeys; no business records are changed.</div><section id="foundations"><div class="section-title"><span class="eyebrow">Visual foundations</span><h2>Grounded in nature. Built for clarity.</h2></div><div class="palette">{palette}</div><div class="guide">{card("<h2>Readable, familiar, welcoming.</h2><p class=muted style=margin-top:10px>Segoe UI typography · 48 px primary controls · 8 px spacing rhythm · soft 12–22 px corners · text-labelled statuses. Light backgrounds support daylight use and clear information hierarchy.</p>")}{card("<h2>Three roles. One visual language.</h2><p class=muted style=margin-top:10px>Farmers see their harvest and decisions. Buyers see availability and agreements. Administrators see queues, measurements and payment evidence. No auction rankings or automatic payment claims.</p>")}</div></section>{gallery}<p class="muted" style="margin-top:45px">AgriFlow UI direction 01 · Based on documentation v1.5 · Self-contained HTML sources prepared for editable Figma import.</p></main></body></html>',encoding='utf-8')
(ROOT/'screen-manifest.json').write_text(json.dumps({'name':'Dambulla AgriFlow','figmaStatus':'Not created: Figma editing tools unavailable in session','screens':SCREENS},indent=2),encoding='utf-8')
print(f'Built {len(SCREENS)} self-contained screens and review board in {ROOT}')
